package com.musiccatalog.controller; import com.musiccatalog.dto.AuthDtos.*; import com.musiccatalog.service.AuthService; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/auth") public class AuthController { private final AuthService service;public AuthController(AuthService s){service=s;} @PostMapping("/register") public TokenResponse register(@Valid @RequestBody Credentials c){return service.register(c);} @PostMapping("/login") public TokenResponse login(@Valid @RequestBody Credentials c){return service.login(c);} }
